#include <bits/stdc++.h>
using namespace std;
using ll = long long;
const int MOD = 1000000007;

ll modPow(ll base, ll exp) {
    ll result = 1;
    base %= MOD;
    while (exp > 0) {
        if (exp & 1) result = (result * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return result;
}

vector<int> combinations;
int prob[10][10];
ll dp1[1 << 20], dp2[1 << 20];

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            int val;
            cin >> val;
            prob[i][j] = (int)((ll)val * modPow(100, MOD - 2) % MOD);
        }
    }

    for (int i = n; i <= 5; i++) {
        prob[i][i] = 1;
    }

    for (int mask = 0; mask < 64; mask++) {
        if (__builtin_popcount(mask) == 3) {
            combinations.push_back(mask);
        }
    }

    for (int mask = 0; mask < (1 << 18); mask++) {
        bool grid[6][6] = {false};
        ll product = 1;
        int bitPos = 0;

        for (int row = 0; row < 6; row++) {
            for (int col = 0; col <= 2; col++) {
                if (mask & (1 << bitPos)) {
                    grid[row][col] = true;
                    product = (product * prob[row][col]) % MOD;
                } else {
                    product = (product * ((1 - prob[row][col] + MOD) % MOD)) % MOD;
                }
                bitPos++;
            }
        }

        int combinedMask = 0;
        for (int idx = 0; idx < (int)combinations.size(); idx++) {
            int combo = combinations[idx];
            int indices[3];
            int cnt = 0;
            for (int k = 0; k < 6; k++) {
                if (combo & (1 << k)) indices[cnt++] = k;
            }

            int i1 = indices[0], i2 = indices[1], i3 = indices[2];
            if ((grid[i1][0] && grid[i2][1] && grid[i3][2]) ||
                (grid[i1][0] && grid[i2][2] && grid[i3][1]) ||
                (grid[i1][1] && grid[i2][0] && grid[i3][2]) ||
                (grid[i1][1] && grid[i2][2] && grid[i3][0]) ||
                (grid[i1][2] && grid[i2][0] && grid[i3][1]) ||
                (grid[i1][2] && grid[i2][1] && grid[i3][0])) {
                combinedMask |= (1 << idx);
            }
        }

        dp1[combinedMask] = (dp1[combinedMask] + product) % MOD;
    }

    for (int mask = 0; mask < (1 << 18); mask++) {
        bool grid[6][6] = {false};
        ll product = 1;
        int bitPos = 0;

        for (int row = 0; row < 6; row++) {
            for (int col = 3; col <= 5; col++) {
                if (mask & (1 << bitPos)) {
                    grid[row][col] = true;
                    product = (product * prob[row][col]) % MOD;
                } else {
                    product = (product * ((1 - prob[row][col] + MOD) % MOD)) % MOD;
                }
                bitPos++;
            }
        }

        int combinedMask = 0;
        for (int idx = 0; idx < (int)combinations.size(); idx++) {
            int combo = combinations[idx];
            int complement = combo ^ 63;
            int indices[3];
            int cnt = 0;
            for (int k = 0; k < 6; k++) {
                if (complement & (1 << k)) indices[cnt++] = k;
            }

            int i1 = indices[0], i2 = indices[1], i3 = indices[2];
            if ((grid[i1][3] && grid[i2][4] && grid[i3][5]) ||
                (grid[i1][3] && grid[i2][5] && grid[i3][4]) ||
                (grid[i1][4] && grid[i2][3] && grid[i3][5]) ||
                (grid[i1][4] && grid[i2][5] && grid[i3][3]) ||
                (grid[i1][5] && grid[i2][3] && grid[i3][4]) ||
                (grid[i1][5] && grid[i2][4] && grid[i3][3])) {
                combinedMask |= (1 << idx);
            }
        }

        dp2[combinedMask] = (dp2[combinedMask] + product) % MOD;
    }

    for (int bit = 0; bit < 20; bit++) {
        for (int mask = (1 << 20) - 1; mask >= 0; mask--) {
            if (mask & (1 << bit)) {
                dp2[mask] = (dp2[mask] + dp2[mask ^ (1 << bit)]) % MOD;
            }
        }
    }

    ll result = 0;
    for (int mask = 0; mask < (1 << 20); mask++) {
        result = (result + dp1[mask] * dp2[((1 << 20) - 1) ^ mask]) % MOD;
    }

    cout << (1 - result + MOD) % MOD << '\n';
    return 0;
}
